        raise AssertionError('dict iter override')
    def keys(self):
        raise AssertionError('keys override')
class K:
    def __hash__(self):
        if active:
            events.append('hash')
            if 'normal' == 'error':
                raise ValueError('key hash failed')
            if 'normal' == 'insert':
                d[2] = 3
            if 'normal' == 'replace':
                d[0] = 4
            if 'normal' == 'clear':
                d.clear()
        return 7
key = K()
d = dict()
d[key] = 1
view = dict.keys(d)
active = True
